import hashlib
import json
import pytest
from subject import _extract_frames, compute_error_fingerprint


@pytest.mark.unit
def test_extract_frames_basic():
    tb = 'Traceback (most recent call last):\n  File "pkg_a/foo.py", line 10, in bar\n    x = 1\n  File "pkg_b/baz.py", line 20, in qux\n    y = 2'
    frames = _extract_frames(tb)
    assert frames == ["pkg_a/foo.py:bar", "pkg_b/baz.py:qux"]


@pytest.mark.unit
def test_extract_frames_memory_address_stripped():
    tb = 'File "0x12345678", line 1, in func'
    frames = _extract_frames(tb)
    assert frames == ["0xADDR:func"]


@pytest.mark.unit
def test_extract_frames_windows_path():
    tb = 'File "C:\\pkg\\foo.py", line 5, in bar'
    frames = _extract_frames(tb)
    assert frames == ["pkg/foo.py:bar"]


@pytest.mark.unit
def test_extract_frames_no_frames():
    tb = "No frames here"
    frames = _extract_frames(tb)
    assert frames == []


@pytest.mark.unit
def test_extract_frames_multiple_frames_order_preserved():
    tb = 'File "a/b.py", line 1, in f1\nFile "c/d.py", line 2, in f2\nFile "e/f.py", line 3, in f3'
    frames = _extract_frames(tb)
    assert frames == ["a/b.py:f1", "c/d.py:f2", "e/f.py:f3"]


@pytest.mark.unit
def test_compute_fingerprint_deterministic():
    tb = 'File "a/b.py", line 1, in f'
    tests = ["test_a", "test_b"]
    fp1 = compute_error_fingerprint(tb, tests)
    fp2 = compute_error_fingerprint(tb, tests)
    assert fp1 == fp2


@pytest.mark.unit
def test_compute_fingerprint_order_independent_tests():
    tb = 'File "a/b.py", line 1, in f'
    fp1 = compute_error_fingerprint(tb, ["test_b", "test_a"])
    fp2 = compute_error_fingerprint(tb, ["test_a", "test_b"])
    assert fp1 == fp2


@pytest.mark.unit
def test_compute_fingerprint_frames_order_matters():
    tb1 = 'File "a/b.py", line 1, in f1\nFile "c/d.py", line 2, in f2'
    tb2 = 'File "c/d.py", line 2, in f2\nFile "a/b.py", line 1, in f1'
    fp1 = compute_error_fingerprint(tb1, ["test_a"])
    fp2 = compute_error_fingerprint(tb2, ["test_a"])
    assert fp1 != fp2


@pytest.mark.unit
def test_compute_fingerprint_sha256_hex():
    tb = 'File "a/b.py", line 1, in f'
    fp = compute_error_fingerprint(tb, ["test_a"])
    assert len(fp) == 64
    assert all(c in "0123456789abcdef" for c in fp)


@pytest.mark.unit
def test_compute_fingerprint_matches_manual_hash():
    tb = 'File "a/b.py", line 1, in f'
    tests = ["test_a"]
    frames = _extract_frames(tb)
    sorted_tests = sorted(tests)
    payload = json.dumps({"frames": frames, "tests": sorted_tests}, sort_keys=True)
    expected = hashlib.sha256(payload.encode()).hexdigest()
    assert compute_error_fingerprint(tb, tests) == expected
